import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type AppleStyleHelloProps = Record<string, any>;

const AppleStyleHello: React.FC<AppleStyleHelloProps> = ({
  fontFamily = "Pacifico",
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  text = "Welcome",
  textColor = "#000000",
  fontSize = 280,
  rainbowMode = true,
  entranceSpeed = 0.8,
}) => {
  {/* Load Google Fonts */}
  useFontLoader([fontFamily]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Parser safety for background
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  const characters = text.split("");

  // Gradient animation for rainbow mode
  const gradientPos = interpolate(
    frame, 
    [0, durationInSeconds * fps], 
    [0, 200], 
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "extend",
    }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: fontFamily,
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          // Fix for cursive fonts getting cut off on parent boundaries
          padding: "50px", 
          transition: "none",
        }}
      >
        {characters.map((char, index) => {
          // Stagger calculation
          const delay = index * (5 * entranceSpeed); 
          
          // Spring for scale/bounce
          const spr = spring({
            frame: frame - delay,
            fps,
            config: {
              damping: 12,
              stiffness: 100,
            },
          });

          // Clip path wipe effect (simulates writing)
          // We wipe from left to right per character
          const wipeProgress = interpolate(
            frame,
            [delay, delay + 15],
            [0, 100],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          // Allow a massive negative right inset once complete to prevent right-edge clipping on overlapping swashes
          const rightInset = interpolate(wipeProgress, [0, 100], [100, -300]);

          // Slight rotation for organic feel
          const rotate = interpolate(
            spr,
            [0, 1],
            [15, 0]
          );

          // Translate Y for "rising" effect
          const translateY = interpolate(
            spr,
            [0, 1],
            [40, 0]
          );

          // Rainbow style props
          const rainbowStyle: React.CSSProperties = rainbowMode
            ? {
                backgroundImage: `linear-gradient(90deg, #ff0000, #ffa500, #ffff00, #008000, #0000ff, #4b0082, #ee82ee, #ff0000)`,
                backgroundSize: "200% auto",
                backgroundPosition: `${gradientPos}% center`,
                WebkitBackgroundClip: "text",
                WebkitTextFillColor: "transparent",
                backgroundClip: "text",
                color: "transparent",
              }
            : {
                color: textColor,
              };

          return (
            <span
              key={index}
              style={{
                fontSize: fontSize,
                display: "inline-block",
                transform: `scale(${spr}) translateY(${translateY}px) rotate(${rotate}deg)`,
                transformOrigin: "bottom center",
                // Expanded vertical and horizontal padding to prevent background-clip: text from cutting off bottom swashes (e.g., 'y', 'g')
                padding: "0.5em 0.2em",
                margin: "-0.5em -0.2em",
                // Re-apply the tight cursive spacing logic overridden by the uniform margin above
                marginLeft: index === 0 ? "-0.2em" : "-0.24em", 
                // The expanded negative values (-300%) ensure swashes that bleed outside the span's strict width or height aren't clipped off
                clipPath: `inset(-300% ${rightInset}% -300% -300%)`,
                lineHeight: 1.1,
                transition: "none",
                ...rainbowStyle,
              }}
            >
              {char === " " ? "\u00A0" : char}
            </span>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default AppleStyleHello;